// ==================== v53.0 (package W5): the rate-basis helpers, the detail loader, the build handshake ====================
// Plan 2.8. Every value path, chart and label that has to tell the three bases apart reads these, never eng.b or the tier.
//   rate    priced on the rate engine (eng.b 'rate'): S1, or S2-lite (the handover prior)
//   branch  the prospect branch (eng.b 'tool' with eng.pc_v52): the v52 tool chain carried by kappa_P (plan 2.3)
//   held    held at v52.0 (eng.held set: the three held records, and 'held_T5b' under a T5b combination, A-6)
function gnBasis(p) {
  const e = (p && p.eng) || {};
  if (e.held != null) return 'held';
  if (e.b === 'rate') return 'rate';
  if (e.b === 'tool' && e.pc_v52 != null) return 'branch';
  return 'held';                                  // nothing else exists at v53.0; anything unpriced keeps its v52 chains
}
// The headline season as a trajectory index 0-9 (the grid's star, the chart's diamond), or null when it lies past the
// grid. Rate basis: the stored eng.rt.kstar (H3: min(9, max(0, peak - a0 - 1)) on the PRICING age a0, which differs from
// the board age on 10 records). Branch and held: the age rule, peak 26 (hitters) / 27 (pitchers) minus the board age.
function gnKstar(p) {
  if (!p) return null;
  if (gnBasis(p) === 'rate') {
    const k = ((p.eng || {}).rt || {}).kstar;
    return (typeof k === 'number' && k >= 0 && k <= 9) ? k : null;
  }
  if (p.a == null) return null;
  const pit = !!(p.p) && String(p.p).indexOf('P') >= 0;
  const k = Math.max(0, (pit ? 27 : 26) - Math.round(p.a));
  return k <= 9 ? k : null;
}
