    if (typeof document === 'undefined' || !document.querySelector) return;
    const meta = document.querySelector('meta[name="gn-build"]');
    const pageBuild = meta ? meta.getAttribute('content') : null;
    if (pageBuild === GN_BUILD) return;
    const KEY = 'gn-build-handshake:' + GN_BUILD;
    let tried = null;
    try { tried = sessionStorage.getItem(KEY); } catch (e) { return; }
    if (tried) {
      try { console.warn('gn-app.js ' + GN_BUILD + ' runs under a page of build ' + (pageBuild || '(none)') + '; already reloaded once this session'); } catch (e) {}
      return;
    }
    try { sessionStorage.setItem(KEY, String(pageBuild || 'none')); } catch (e) { return; }
    const here = String(location.href).split('#')[0];
    const urls = [here];
    document.querySelectorAll('script[src]').forEach(function (el) {
      try { const u = new URL(el.getAttribute('src') || '', here); if (u.origin === location.origin) urls.push(u.href); } catch (e) {}
    });
    Promise.all(urls.map(function (u) { return fetch(u, {cache: 'reload'}).catch(function () { return null; }); }))
      .then(function () { location.reload(); });
