function updateLabels() {
  // DO-5: the mode line said "Raw" for a mode every button on the page calls Risk-Adj, "3 years"
  // when the year mode was single-season year 3, and "$ / ... / RA" where that RA was the blend.
  // It now uses the controls' own words, in the controls' order.
  // v53.0 (plan 2.8, A-18): the Pure end applies at the one-season headline view only. At Career years 2 and up the
  // blend control is inert (the way gn-ros-v46.js disables the sliders in ROS mode) and its readout says why.
  const pureOn = gnPureEndActive();
  const blendRO = pureOn
    ? (BLEND === 0 ? '100% RA' : (BLEND === 100 ? '100% Pure' : (100-BLEND) + '% RA / ' + BLEND + '% Pure'))
    : 'Pure blend applies to the one-season headline view only';
  const modeStr = MODE === 'dollar' ? '$ value' : 'Risk-Adj';
  const yearsStr = YEARS === 1 ? '1 year' : (YEAR_MODE === 'single' ? 'year ' + YEARS + ' only' : YEARS + ' years cumulative');
  $('modeLabel').textContent = modeStr + ' / ' + yearsStr + (pureOn ? ' / blend ' + blendRO : ' / blend: one-season view only');
  $('blendReadout').textContent = blendRO;
  let yearsRO;
  if (YEARS === 1) yearsRO = '1 year (headline season)';
  else if (YEAR_MODE === 'single') yearsRO = 'Year ' + YEARS + ' only';
  else yearsRO = YEARS + ' year career (sum yrs 1-' + YEARS + ')';
  $('yearsReadout').textContent = yearsRO;
  // DO-2: the sliders announced a bare "0" and "1"; aria-valuetext mirrors the readout beside them.
  $('blendSlider').setAttribute('aria-valuetext', blendRO);
  // inert, not disabled: gn-ros-v46.js's wrapper owns .disabled (ROS mode) and would undo it on the way out
  const _bs = $('blendSlider');
  if (_bs) { _bs.inert = !pureOn; _bs.classList.toggle('gn-inert', !pureOn); _bs.setAttribute('aria-disabled', pureOn ? 'false' : 'true'); }
  $('yearsSlider').setAttribute('aria-valuetext', yearsRO);
  // This function now owns all four readouts, so the click handlers and the localStorage restore
  // cannot drift from each other -- they all call here.
  $('yearModeReadout').textContent = YEAR_MODE === 'single' ? 'Single season' : 'Cumulative';
  // DO-4: at Career years 1, getValue takes the blendedRaw path and never reaches fadeAdjustedTj,
  // so the bust-risk toggle changes nothing -- every one of the 1,116 T3/T4 trajectories valued
  // identically either way (measured 2026-09-11) while the readout still flipped. Say where it applies.
  const fadeRO = FADE_MODE === 'on' ? 'Bust risk off (prospects)' : 'Risk-adj';
  $('fadeModeReadout').textContent = YEARS === 1
    ? fadeRO + ' \u2014 applies from Career years 2 up; year 1 is unaffected'
    : fadeRO;
  $('fadeModeToggle').classList.toggle('inert', YEARS === 1);
}


