  const gStr = (g>=0?'+$':'-$') + Math.abs(g).toFixed(2)
    + (window.__gnEkgNarrowed ? ' org-wide' : '');
  let html='<div style="font-weight:700;border-bottom:1px solid #BD9B60;margin-bottom:4px;padding-bottom:3px">'+_iesc(GNDAILY.dates[node.sp-1])+'  —  <span style="color:'+(g>=0?'#7CFC9A':'#ff9b9b')+'">'+gStr+'</span></div>';
  var _EKGDOT={green:'#16a34a',purple:'#7c3aed',blue:'#2563eb',red:'#dc2626',yellow:'#d4a017'};
  var _parts=(node.parts&&node.parts.length)?node.parts:[{c:node.c,t:node.t,a:node.a,d:node.d,g:node.g}];
  _parts.forEach(function(pt){
    html+='<div style="margin-top:4px"><span style="color:'+(_EKGDOT[pt.c]||'#fff')+';font-weight:700">●</span> '+_iesc(pt.t||'')+'</div>';
    if(pt.a&&pt.a.length) html+='<div style="margin-left:11px"><span style="color:#7CFC9A">In:</span> '+_iesc(pt.a.join(', '))+'</div>';
    if(pt.d&&pt.d.length) html+='<div style="margin-left:11px"><span style="color:#ff9b9b">Out:</span> '+_iesc(pt.d.join(', '))+'</div>';
  });
