    rows += gnSpineRow(5, 'Pace', '§13', 'retired on the rate basis: the multiplier is fixed at 1.00 (SPEC 8.3)', 'retired', '', true);
    var j = p.inj || null, im = (p.im != null ? p.im : 1), t6, w6 = '', onEspn = /^(IL-|OUT)/.test(String(p.il || ''));
