  // (gnPmAllowed, gnPaceNote, GN_ABSORB) is no longer called from any panel. The definitions stay (2.10 KEEP-DEF).
  rows+=gnSpineRow(5,'Pace','§13','retired at v53.0 on every basis: the multiplier is fixed at 1.00 (SPEC 8.3)','retired','',true);

