    const note = t => `<div class="formula-row note"><span class="value">${_iesc(t)}</span></div>`;
    const MTL = { F3: 'rate projection (\u03b2, \u03b3, C, \u03b4)', F4: 'full season and intensity', F5U: 'expected share U',
      F5UG: 'reliever share UG', F6: 'survival SIGMA', F7: 'role chain', LM: 'league means', w: 'lag weights',
      K: 'prior strength K', kappa: 'level carry \u03ba_P', Sprime: 'return survival S\u2032' };
    const links = ids => '<div class="formula-row note"><span class="value">Model tables: ' + ids.map(id =>
      `<a href="gn-model-tables.html#${id}" target="_blank" rel="noopener">${_iesc(MTL[id])}</a>`).join(' \u00b7 ') + '</span></div>';
    const uName = kd => (kd.grp === 'H' ? 'PA' : 'IP');
    const kindName = kd => (kd.grp === 'H' ? 'Batting' : 'Pitching') + ' chain (' + kd.grp + ')';
    const gfKey = kd => { const G = GM.Gfull || {}; for (const q of ['C', 'H', 'SP', 'RP']) if (G[q] === kd.Gf) return q; return kd.grp; };
    const intUnit = kd => (kd.grp === 'H' ? 'PA per game' : (kd.grp === 'SP' ? 'IP per start' : 'IP per appearance'));
    const gUnit = kd => (kd.grp === 'H' ? 'games' : (kd.grp === 'SP' ? 'starts' : 'appearances'));
    const termTable = (title, names, vals) => `<details class="gn-terms"><summary style="cursor:pointer;font-size:11px;color:#6e6d68;">${_iesc(title)}</summary><table style="font-size:11px;border-collapse:collapse;margin:2px 0 4px 16px;">`
      + names.map((nm, q) => `<tr><td style="padding:0 12px 0 0;color:#6e6d68;">${_iesc(nm)}</td><td style="text-align:right;font-variant-numeric:tabular-nums;">${g6(vals[q])}</td></tr>`).join('')
      + '</table></details>';
    const _isFA = !!(p.o && p.o.toString().startsWith('FA'));
    const orgBadge = _isFA ? ('Free agent' + (p.o.length > 2 ? ' ' + p.o.toString().slice(2).trim() : '')) : (p.rn ? (p.rn + (p.l ? ' (' + p.l + ')' : '')) : (p.o || '\u2014'));
    const typeLabels = {'T1':'T1 (Established peak vet)','T2':'T2 (Past-peak vet)','T3':'T3 (Young MLB-tested)','T4':'T4 (Pure prospect)','T5':'T5 (Depth)'};
