const RULE5 = {"Brent Headrick":{"by":"High Cheddar","from":"Kansas Sunflower Seeds"},"Payton Tolle":{"by":"KC Gray Hotdogs","from":"River Cats"},"Colin Holderman":{"by":"The Balking Dead","byO":"Balking Dead","from":"Kansas Sunflower Seeds"},"Daniel Palencia":{"by":"River Cats","from":"C-Town Liquors","recaptured":true,"recaptured_by":"C-Town Liquors","note":"Released to waivers by River Cats Aug 22; reacquired by C-Town (the club he was drafted from) and placed on Clam Shack per Art. V(b)(4)(C)(ii). No option charged \u2014 V(b)(4)(C)(i) exemption granted by the commissioner Aug 24, 2026."},"Kyle Harrison":{"by":"High Cheddar","from":"KC Gray Hotdogs"},"Parker Messick":{"by":"Dirty Spikes","from":"KC Gray Hotdogs"},"Dillon Dingler":{"by":"High Cheddar","from":"Midwest Bears","reverted":true,"reverted_on":"Sep 7","reverted_note":"This was a RELEASE, not a demotion. High Cheddar dropped him to waivers Sep 7 \u2014 the one transaction Art. V(b)(4)(B)(iii) and (C) leave open to a drafting manager, who may not trade or demote a draftee \u2014 and hicheddar AAA acquired him from the pool Sep 10, three days later, by which time he was an ordinary player. Nothing in that sequence is illegal, and no reclamation right survives it: Midwest Bears\u2019 two-day window expired Sep 9, and Adv. Op. 2026-R5-02 Holding 3 extinguishes every reclamation interest on expiry. The Art. V(b)(4)(C)(i) exemption cannot apply either \u2014 it runs only to the club he was drafted FROM and only inside two days. Art. V(b)(4)(C)(iii) governs: he reverted to ordinary property on clearance, and that clause expressly grants no exception to VI(b)(3). THE OPTION IS CHARGED (Sep 10) \u2014 VI(b)(3) asks only what the most-immediate prior roster status was, and it was MLB; time spent in the free-agent pool does not bear on it. On the keeper tag, Holding 5 leaves a reacquired draftee in the drafting organisation\u2019s hands as ordinary property under the rules as written, and \u00a7IV names this exact sequence, declines to bar it by opinion, and refers an anti-circumvention amendment to the membership for the next-season vote. Commissioner\u2019s determination pending."},"AJ Blubaugh":{"by":"Dirty Spikes","from":"KC Gray Hotdogs"},"Jonathan Aranda":{"by":"KC Gray Hotdogs","from":"River Cats"},"Luis Garcia Jr.":{"by":"C-Town Liquors","from":"Midwest Bears"},"Edwin Diaz":{"by":"KC Gray Hotdogs","from":"Midwest Bears"},"Kyle Tucker":{"by":"River Cats","from":"KC Gray Hotdogs"},"Emilio Pagan":{"by":"KC Gray Hotdogs","from":"C-Town Liquors"},"Byron Buxton":{"by":"High Cheddar","from":"Midwest Bears"}}; // July 14, 2026 Rule 5 draft — pick: {by: drafting club, from: original club}
const OPT_NAMES = [...new Set([...PLAYERS.map(p => p.n), ...Object.keys(OPTIONS_DATA)])].sort();
const OPT_PLAYER = {};
PLAYERS.forEach(p => { if (!(p.n in OPT_PLAYER)) OPT_PLAYER[p.n] = p; });

function optColor(rem) {
  if (rem <= 0) return { bg: '#f4c7c3', fg: '#9c1c14', label: 'OUT of options' };
  if (rem === 1) return { bg: '#fce8b2', fg: '#7a5c00', label: '1 option left' };
  return { bg: '#b7e1cd', fg: '#0f6b34', label: '2 options left' };
}

function renderOptions(name) {
  const body = document.getElementById('optionsBody');
  const data = OPTIONS_DATA[name] || { remaining: 2, burns: 0, events: [] };
  const pendingCount = (data.events || []).filter(e => e.pending_burn).length;
  const p = OPT_PLAYER[name];
  // OPT-5: the counter code four hundred lines up defaults this with
  // `rem === undefined ? 2 : rem`; this read did not, so a record missing the field
  // would render "undefined / 2" in green. No record lacks it today.
  const rem = (data.remaining === undefined ? 2 : data.remaining);
  const c = optColor(rem);
  let sub;
  if (p) { sub = `${p.p} | age ${p.a} | ${p.o && p.o.startsWith('FA') ? 'Free Agent' : (p.rn || p.o)}`; }
  else { const loc = (data.events || []).map(e => e.team).find(t => t && t !== 'Waivers'); sub = loc ? `Currently: ${loc} \u00b7 not in valuation workbook` : 'Free agent / not rostered'; }
  const rows = (data.events || []).map(e => {
    const burn = e.burn, pend = e.pending_burn;
    const bg = burn ? '#fdecea' : (pend ? '#fff6e6' : 'transparent');
    const badge = burn
      ? '<span style="color:#9c1c14; font-weight:600; font-size:11px; white-space:nowrap;">\u2212 1 option</span>'
      : (pend ? '<span style="color:#b06f00; font-weight:600; font-size:11px; white-space:nowrap;">\u2212 1 option (pending)</span>'
              : '<span style="color:#9c9b96; font-size:11px; white-space:nowrap;"></span>');
    const dotColor = burn ? '#d11a0f' : (pend ? '#e0a800' : '#c9c8c3');
    return `<div class="formula-row" style="display:grid; grid-template-columns: 64px 1fr auto; gap:10px; align-items:baseline; background:${bg}; ${burn ? 'color:#7a1610;' : (pend ? 'color:#7a5c00;' : '')}">
      <span class="label" style="color:${burn ? '#9c1c14' : (pend ? '#7a5c00' : 'var(--color-text-secondary,#6e6d68)')}; font-size:11px;">${_iesc(e.date)}</span>
      <span class="value" style="text-align:left; white-space:normal;"><span style="display:inline-block;width:7px;height:7px;border-radius:50%;background:${dotColor};margin-right:7px;"></span>${_iesc(e.detail)} <span style="color:#9c9b96;font-size:10px;">(${_iesc(e.type)})</span></span>
      ${badge}
    </div>`;
  }).join('');
  const history = (data.events && data.events.length)
    ? rows
    : '<div class="formula-row" style="display:grid; grid-template-columns:1fr;"><span class="value" style="text-align:left;color:#6e6d68;">No ' + GN_DAILY_Y + ' transactions \u2014 full 2 options available.</span></div>';

  body.innerHTML = `
    <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:12px; margin-bottom:14px;">
      <div>
        <div style="font-size:16px; font-weight:500;">${_iesc(name)}${(typeof RULE5!=='undefined'&&RULE5[name])?' <span style="background:#13274F;color:#fff;font-size:10px;font-weight:700;letter-spacing:.05em;border-radius:5px;padding:2px 7px;vertical-align:2px;">RULE 5</span>':''}</div>
        <div style="font-size:12px; color:var(--color-text-secondary,#6e6d68);">${_iesc(sub)}</div>
      </div>
      <div style="text-align:center; background:${c.bg}; color:${c.fg}; border-radius:10px; padding:8px 16px; min-width:120px;">
        <div style="font-size:24px; font-weight:600; line-height:1;">${rem} <span style="font-size:13px; font-weight:400;">/ 2</span></div>
        <div style="font-size:11px; font-weight:600; margin-top:2px;">${c.label}</div>
      </div>
    </div>
    <div class="player-card">
      <div class="formula-section">
        <h4>${GN_DAILY_Y} AAA Option Status</h4>
        <div class="formula-row"><span class="label">Options burned this season</span><span class="value">${data.burns}</span></div>
        <div class="formula-row"><span class="label">Options remaining (2 \u2212 burned)</span><span class="value">${rem}</span></div>
        ${pendingCount ? `<div class="formula-row"><span class="label" style="color:#b06f00;">Pending (accepted, not processed)</span><span class="value" style="color:#b06f00;">${pendingCount} move(s) will burn on processing \u2192 remaining would become ${Math.max(0, rem - pendingCount)}</span></div>` : ''}
        ${rem === 0 ? '<div class="formula-row"><span class="label" style="color:#9c1c14;">Restriction</span><span class="value" style="color:#9c1c14;">Cannot be optioned/demoted again (Rulebook VI(c))</span></div>' : ''}
        ${(typeof RULE5!=='undefined'&&RULE5[name]) ? `<div class="formula-row r5-note"><span class="label" style="color:#13274F; font-weight:600;">RULE 5 (drafted Jul 14, 2026 by ${_iesc(RULE5[name].by)})${RULE5[name].reverted?' \u00b7 RESTRICTIONS ENDED '+_iesc(RULE5[name].reverted_on||''):''}</span><span class="value" style="color:#13274F;">${RULE5[name].reverted ? '<b>No longer under Rule 5 restrictions.</b> ' + _iesc(RULE5[name].reverted_note||'') : `May NOT be demoted from the MLB roster regardless of options remaining. Exceptions: ${_iesc(RULE5[name].from)} (original club) recaptures him if an illegal demotion is attempted, or claims him off waivers if ${_iesc(RULE5[name].by)} drops him.${RULE5[name].recaptured ? ' <b>Recaptured by ' + _iesc(RULE5[name].recaptured_by||RULE5[name].from) + ' — exempt, legal terminal state.</b> ' + _iesc(RULE5[name].note||'') : ''}`}</span></div>` : ''}
      </div>
      <div class="formula-section">
        <h4>${GN_DAILY_Y} Transaction History <span style="font-weight:400;color:#9c9b96;font-size:11px;">(red = burns an option)</span></h4>
        ${history}
      </div>
    </div>`;
}

const optionsSearch = document.getElementById('optionsSearch');
const optionsResults = document.getElementById('optionsResults');
const OPT_CAP = 30;
optionsSearch.addEventListener('input', () => {
  const q = gnFold(optionsSearch.value.trim());
  // OT-4: the Inspector answers from the first keystroke; this box ignored one-character queries.
  if (!q) { optionsResults.classList.remove('open'); optionsResults.innerHTML = ''; return; }
  // OT-3: one substring test, so "rodriguez julio" found nobody here and the player one card up.
  const qTokens = q.split(' ').filter(Boolean);
  const allMatches = OPT_NAMES.filter(n => { const fn = gnFold(n); return qTokens.every(t => fn.indexOf(t) !== -1); });
  const matches = allMatches.slice(0, OPT_CAP);
  if (matches.length === 0) {
    optionsResults.innerHTML = '<div class="inspector-result" style="color:#9c9b96;">No matches</div>';
  } else {
    optionsResults.innerHTML = matches.map(n => {
      const pl = OPT_PLAYER[n];
      const rem = (OPTIONS_DATA[n] || {}).remaining;
      const remShow = (rem === undefined ? 2 : rem);
      const dot = remShow <= 0 ? '#d11a0f' : (remShow === 1 ? '#e0a800' : '#1a9c4f');
      const meta = pl ? `${pl.p}, ${pl.o && pl.o.startsWith('FA') ? 'FA' : pl.o}` : 'FA';
      return `<div class="inspector-result" data-n="${_iesc(n)}"><span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${dot};margin-right:7px;"></span>${_iesc(n)} <span style="color:#6e6d68;font-size:11px;">(${_iesc(meta)}) · ${remShow}/2</span></div>`;
    }).join('');
  }
  // OT-2: "an" matches 626 names and thirty were shown with nothing saying so. Same note the
  // Inspector carries; no data-n on the row, so it stays out of the click and ARIA wiring.
  if (allMatches.length > matches.length) {
    optionsResults.insertAdjacentHTML('afterbegin',
      '<div class="inspector-result" style="color:#9c9b96;cursor:default;">Top ' + matches.length
      + ' of ' + allMatches.length.toLocaleString() + ' matches \u00b7 narrow the search to see the rest</div>');
  }
  optionsResults.classList.add('open');
  [...optionsResults.querySelectorAll('.inspector-result[data-n]')].forEach(el => {
    el.addEventListener('click', () => {
      renderOptions(el.dataset.n);
      optionsSearch.value = el.dataset.n;
      optionsResults.classList.remove('open');
      // OT-6: the record panel is replaced silently. Announce through the shared status region.
      if (typeof gnAnnounce === 'function') gnAnnounce(el.dataset.n + ' option record shown.');
    });
  });
});
optionsSearch.addEventListener('focus', () => {
  // OPT-2: wireRows() writes optionsSearch.value without touching optionsResults, so
  // revealing the cached markup showed the results of a query the box no longer held.
  // Regenerate from the current value instead of re-opening whatever is there.
  if (optionsSearch.value.trim().length >= 1) optionsSearch.dispatchEvent(new Event('input'));
});

// ---- Options burn-count filter buttons (Aug 18, 2026 hotfix) ----
(function(){
  if(!document.getElementById('optFilt1')) return;
  const groups={one:[],two:[],nc:[],r5:(typeof RULE5!=='undefined'?Object.keys(RULE5):[])};
  Object.keys(OPTIONS_DATA).forEach(n=>{
    const b=(OPTIONS_DATA[n].burns||0);
    if(b===1)groups.one.push(n); else if(b===2)groups.two.push(n); else if(b>2)groups.nc.push(n);
  });
  ['one','two','nc','r5'].forEach(k=>groups[k].sort((a,b)=>a.localeCompare(b)));
  document.getElementById('optCnt1').textContent=groups.one.length;
  document.getElementById('optCnt2').textContent=groups.two.length;
  document.getElementById('optCntNC').textContent=groups.nc.length;
  document.getElementById('optCntR5').textContent=groups.r5.length;
  const listEl=document.getElementById('optFilterList');
  const btns={one:document.getElementById('optFilt1'),two:document.getElementById('optFilt2'),nc:document.getElementById('optFiltNC'),r5:document.getElementById('optFiltR5')};
  let openKey=null;
  function lastBurn(n){
    for(const e of (OPTIONS_DATA[n].events||[])){ if(e.burn) return e.date; }  // newest-first
    return '';
  }
  function metaOf(n){
    const p=OPT_PLAYER[n];
    if(!p){ const d=OPTIONS_DATA[n]; const loc=(d.events||[]).map(e=>e.team).find(t=>t&&t!=='Waivers'); return loc||'FA'; }
    return `${p.p} \u00b7 ${p.o&&p.o.startsWith('FA')?'FA':p.o}`;
  }
  function render(k){
    const names=groups[k];
    if(k==='r5'){
      const rows=names.map(n=>{
        const r5=RULE5[n]; const p=OPT_PLAYER[n];
        let st,stc;
        // v50.20: test the roster LEVEL field, not the ESPN roster name (High Cheddar's MLB squad is "TARPS OFF!!!",
        // River Cats' is "Joey Chestnuts", so four legal players read as illegal demotions); honour the recapture record.
        const drafter=(r5.byO||r5.by);
        if(r5.recaptured){ st='RECAPTURED by '+(r5.recaptured_by||r5.from)+' \u2014 exempt, legal terminal state'; stc='#0f6b34'; }
        // v51.5: a draftee RELEASED to waivers leaves the MLB roster by the one door the rules
        // leave open, and on clearance he is ordinary property. Without this branch he lands in
        // the demotion test below purely because he is back with his drafting organisation, and
        // the list accuses a manager of an illegal move he did not make.
        else if(r5.reverted){ st='REVERTED '+(r5.reverted_on||'')+' \u2014 released to waivers, re-signed as ordinary property \u2014 legal, no restriction'; stc='#13274F'; }
        else if(p && p.o===drafter && p.l==='MLB'){ st='ON MLB ROSTER \u2713'; stc='#0f6b34'; }
        else if(p && p.o===drafter){ st='\u26a0 ILLEGAL DEMOTION ('+(p.l||'AAA')+' roster) \u2014 '+r5.from+' may recapture'; stc='#9c1c14'; }
        else if(!p || (p.o&&p.o.startsWith('FA'))){ st='\u26a0 ON WAIVERS \u2014 '+r5.from+' may recapture'; stc='#9c1c14'; }
        else { st='\u26a0 NO LONGER WITH '+r5.by.toUpperCase()+' \u2014 review'; stc='#b06f00'; }
        return `<div class="opt-fl-row" role="option" aria-selected="false" data-n="${_iesc(n)}">`+
          `<span style="font-weight:500;">${_iesc(n)}</span>`+
          `<span class="m">${p?_iesc(p.p)+' · ':''}drafted by ${_iesc(r5.by)} · from ${_iesc(r5.from)}</span>`+
          `<span class="s" style="color:${stc};">${_iesc(st)}</span></div>`;
      }).join('');
      listEl.innerHTML=`<div class="opt-fl-head" style="color:#13274F;">${names.length} players selected in the July 14, 2026 Rule 5 draft</div>`+
        `<div class="opt-fl-r5note"><b>Roster restriction:</b> a Rule 5 selection may NOT be traded or demoted from the MLB roster, regardless of remaining options. The one transaction open to the drafting manager is <b>release to waivers</b> \u2014 and <b>a release is not a demotion</b>. So a draftee leaves that roster three ways. (1) The <b>original manager recaptures him</b> when an illegal demotion is attempted. (2) After a release, the <b>original manager reclaims him within two days</b> \u2014 no option charged, either level, Art. V(b)(4)(C)(i)\u2013(ii). (3) The <b>original manager passes</b>: the window expires and every reclamation right with it (Adv. Op. 2026-R5-02, Holding 3), and he clears to <b>ordinary property</b> under Art. V(b)(4)(C)(iii) \u2014 keeper-eligible on ordinary terms (Holding 5) even if the drafting organisation signs him back, and because (C)(iii) grants no exception to VI(b)(3), a AAA signing off an MLB roster still charges an option.</div>`+
        `<div class="opt-fl-scroll" role="listbox" tabindex="0" aria-label="Filtered players, use the arrow keys">${rows}</div>`;
      wireRows(); return;
    }
    const title = k==='one' ? `${names.length} players have burned exactly 1 option \u2014 1 remaining each`
              : k==='two' ? `${names.length} players have burned both options \u2014 OUT of options (Rulebook VI(c))`
              : (names.length ? `${names.length} players OVER the 2-option limit \u2014 Rulebook VI(b) violation` : 'Non-compliance check');
    const col = k==='one' ? '#7a5c00' : '#9c1c14';
    if(k==='nc' && !names.length){
      listEl.innerHTML=`<div class="opt-fl-head" style="color:#0f6b34;">${title}</div><div class="opt-fl-clear">\u2713 ALL CLEAR \u2014 every tracked player is at or under the 2-option season limit.</div>`;
      return;
    }
    const rows=names.map(n=>{
      const d=OPTIONS_DATA[n]; const lb=lastBurn(n);
      return `<div class="opt-fl-row" role="option" aria-selected="false" data-n="${_iesc(n)}">`+
        `<span style="font-weight:500;">${_iesc(n)}</span><span class="m">${_iesc(metaOf(n))}</span>`+
        `<span class="s" style="color:${col};">${d.burns} burned · ${d.remaining} left${lb?` · last: ${_iesc(lb)}`:''}</span></div>`;
    }).join('');
    listEl.innerHTML=`<div class="opt-fl-head" style="color:${col};">${title}</div><div class="opt-fl-scroll" role="listbox" tabindex="0" aria-label="Filtered players, use the arrow keys">${rows}</div>`;
    wireRows();
  }
  function wireRows(){
    // OT-1: these rows were plain divs with click handlers -- no tab stop, no role, so the whole
    // filter was mouse-only. Giving 182 rows their own tab stops would be worse than the disease,
    // so the scroll container is the single tab stop and the arrows move within it, the same
    // listbox shape the four search dropdowns already use.
    const rows=[...listEl.querySelectorAll('.opt-fl-row')];
    const box=listEl.querySelector('.opt-fl-scroll');
    let active=-1;
    rows.forEach((el,i)=>{ if(!el.id) el.id='optfl-row-'+i; });
    function stamp(){
      rows.forEach((el,i)=>el.setAttribute('aria-selected', i===active?'true':'false'));
      if(box){
        if(active>=0&&rows[active]) box.setAttribute('aria-activedescendant', rows[active].id);
        else box.removeAttribute('aria-activedescendant');
      }
    }
    function openRow(el){
        const nm=el.dataset.n;
        renderOptions(nm);
        if (typeof gnAnnounce === 'function') gnAnnounce(nm + ' option record shown.');
        optionsSearch.value=nm;
        // OPT-2: the search box now names this player, so the cached result list for the
        // previous query must go with it or refocusing the box offers the wrong names.
        optionsResults.innerHTML=''; optionsResults.classList.remove('open');
        // OPT-4: block:'start' put the record's name and its "X / 2 options left" chip --
        // the two things this click was for -- under the sticky masthead. Land below it.
        const _bd=document.getElementById('optionsBody');
        const _hd=document.querySelector('.gn-header');
        // scroll-margin-top, not a computed scrollTo offset: the masthead is position:sticky and
        // its height changes with the viewport, and scrollIntoView honours the margin whereas a
        // programmatic smooth window.scrollTo is silently ignored by some engines (measured: the
        // right target was computed and the page never moved).
        _bd.style.scrollMarginTop=((_hd?_hd.getBoundingClientRect().height:0)+12)+'px';
        _bd.scrollIntoView({behavior:'smooth',block:'start'});
    }
    rows.forEach((el,i)=>el.addEventListener('click',()=>{ active=i; stamp(); openRow(el); }));
    if(box){
      box.addEventListener('keydown',function(e){
        const k=e.key;
        if(!rows.length) return;
        if(k==='ArrowDown'||k==='ArrowUp'){
          e.preventDefault();
          active=(active<0)?(k==='ArrowDown'?0:rows.length-1)
                           :(active+(k==='ArrowDown'?1:-1)+rows.length)%rows.length;
          stamp(); rows[active].scrollIntoView({block:'nearest'});
        } else if(k==='Home'){ e.preventDefault(); active=0; stamp(); rows[0].scrollIntoView({block:'nearest'}); }
        else if(k==='End'){ e.preventDefault(); active=rows.length-1; stamp(); rows[active].scrollIntoView({block:'nearest'}); }
        else if(k==='Enter'||k===' '){ if(active>=0&&rows[active]){ e.preventDefault(); openRow(rows[active]); } }
      });
    }
    stamp();
  }
  function syncChips(){
    Object.keys(btns).forEach(x=>{
      const on = (openKey===x);
      btns[x].dataset.on = on?'1':'0';
      btns[x].setAttribute('aria-pressed', on?'true':'false');
      btns[x].setAttribute('aria-expanded', on?'true':'false');
    });
  }
  Object.keys(btns).forEach(k=>{
    btns[k].addEventListener('click',()=>{
      if(openKey===k){ openKey=null; listEl.style.display='none'; syncChips(); return; }
      openKey=k;
      syncChips();
      render(k);
      listEl.style.display='block';
      // OT-1: move focus into the list that just opened, so the arrows work without hunting for it
      const box=listEl.querySelector('.opt-fl-scroll'); if(box) box.focus();
    });
  });
})();


document.addEventListener('click', (e) => {
  // OPT-1: both search panels use .inspector-search-wrap, so the old test closed the
  // Inspector's list for a click anywhere in EITHER wrap and never closed the Options
  // list at all. Compare against each input's own wrap instead.
  const wrap = e.target.closest('.inspector-search-wrap');
  if (wrap !== inspectorSearch.closest('.inspector-search-wrap')) inspectorResults.classList.remove('open');
  if (wrap !== optionsSearch.closest('.inspector-search-wrap')) optionsResults.classList.remove('open');
});

// Initial render after Chart.js loads
function themeCharts(){
  if (typeof Chart === 'undefined') return;
  Chart.defaults.font.family = '"Lato","Helvetica Neue",Arial,sans-serif';
  Chart.defaults.font.size = 11;
  Chart.defaults.color = '#16233a';
  Chart.defaults.borderColor = 'rgba(11,44,92,.10)';
  Chart.defaults.plugins.legend.labels.color = '#16233a';
  Chart.defaults.plugins.tooltip.backgroundColor = '#0B2C5C';
  Chart.defaults.plugins.tooltip.titleColor = '#E5A227';
  Chart.defaults.plugins.tooltip.bodyColor = '#F1ECDD';
  Chart.defaults.plugins.tooltip.borderColor = '#E5A227';
  Chart.defaults.plugins.tooltip.borderWidth = 1;
  Chart.defaults.plugins.tooltip.titleFont = { family: '"Lato",Arial,sans-serif', weight: '700', size: 12 };
}
let _gnChartTries = 0;
function tryRenderCharts() {
  if (typeof Chart !== 'undefined') { themeCharts(); renderAllCharts(); return; }
  if (++_gnChartTries > 100) {   // v50.20: ~10 s, then stop polling (offline PWA: the CDN copy of Chart.js is not cached)
    document.querySelectorAll('.no-data-msg').forEach(el => { el.style.display = 'block'; el.textContent = 'Charts need Chart.js from the CDN and it did not load (offline?). Values, verdicts, the Inspector and the Options Tracker work without it.'; });
    return;
  }
  setTimeout(tryRenderCharts, 100);
}
tryRenderCharts();
try { performance.mark('gn-app:end'); performance.measure('gn-app', 'gn-app:start', 'gn-app:end'); } catch (e) {}   // v53.0 (W5, plan 6.6): the last statement

